using System; using System.IO; using System.Collections.Generic; using System.Drawing; using System.Drawing.Imaging; using System.Runtime.InteropServices;
public static class TreeArea { public static void Run(string path) { using(var r=new BinaryReader(File.OpenRead(path))) {int prev=0, drops=0; var areas=new List<string>(); for(int i=0;i<209;i++) { int n=r.ReadInt32(); using(var b=new Bitmap(836,471,PixelFormat.Format32bppArgb)) using(var g=Graphics.FromImage(b)) {g.Clear(Color.Black); for(int j=0;j<n;j++){var p=new PointF[3];for(int k=0;k<3;k++){p[k]=new PointF(r.ReadSingle()*836,(1-r.ReadSingle())*471);}g.FillPolygon(Brushes.White,p);}var d=b.LockBits(new Rectangle(0,0,836,471),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);byte[] a=new byte[Math.Abs(d.Stride)*471];Marshal.Copy(d.Scan0,a,0,a.Length);b.UnlockBits(d);int count=0;for(int q=0;q<a.Length;q+=4)if(a[q]>0)count++;if(i<201 && count<prev){drops++;Console.WriteLine("DROP "+i+" "+prev+" "+count);}areas.Add(count.ToString());if(i<201)prev=count;}} File.WriteAllLines(Path.Combine(Path.GetDirectoryName(path),"tree-area.txt"),areas); Console.WriteLine("drops "+drops);}}}
